const issueKey = $json.issue_key;
const summary = $json.summary;
const executionStatus = $json.execution_status;
const totalDefects = $json.total_defects || 0;
const defects = $json.defects || [];
const executionResults = $json.execution_results || [];

const iteration = $json.iteration || "N/A";
const maxIterations = $json.max_iterations || "N/A";
const acCoveragePercentage = $json.ac_coverage_percentage || "N/A";
const qualityScore = $json.quality_score || "N/A";
const criticStatus = $json.critic_status || "N/A";
const criticFeedback = $json.critic_feedback || [];

const totalTests = executionResults.length;
const passed = executionResults.filter(r => r.execution_status === "PASS").length;
const failed = executionResults.filter(r => r.execution_status === "FAIL").length;

let report = `
AI QA Agent Execution Report

Story: ${issueKey}
Summary: ${summary}

Quality Gate Summary:
Critic Status: ${criticStatus}
AC Coverage: ${acCoveragePercentage}%
Quality Score: ${qualityScore}
Review Iteration: ${iteration} of ${maxIterations}

Critic Feedback:
${criticFeedback.length > 0 ? criticFeedback.map(f => `- ${f}`).join("\n") : "- No critic feedback available."}

Test Execution Summary:
Total Tests: ${totalTests}
Passed: ${passed}
Failed: ${failed}
Overall Execution Status: ${executionStatus}

Execution Evidence:
`;

executionResults.forEach(r => {
  report += `

${r.test_case_id} - ${r.execution_status}
Scenario: ${r.scenario}
Type: ${r.type}
Method: ${r.api_method}
URL: ${r.api_url}
Expected Status: ${r.expected_status}
Actual Status: ${r.actual_status}
Actual Result: ${r.actual_result}

Response Body:
${JSON.stringify(r.response_body, null, 2)}

Defect Required: ${r.defect_required ? "Yes" : "No"}
`;
});

if (defects.length > 0) {
  report += `

Defects Identified:
`;

  defects.forEach(d => {
    report += `

${d.defect_id}
Summary: ${d.defect_summary}
Severity: ${d.severity}
Priority: ${d.priority}
Status: ${d.status}
Description:
${d.defect_description}
`;
  });
} else {
  report += `

No defects identified.
`;
}

return [
  {
    json: {
      issue_key: issueKey,
      summary,
      critic_status: criticStatus,
      ac_coverage_percentage: acCoveragePercentage,
      quality_score: qualityScore,
      iteration,
      max_iterations: maxIterations,
      execution_status: executionStatus,
      total_tests: totalTests,
      passed,
      failed,
      total_defects: totalDefects,
      defects,
      execution_results: executionResults,
      report
    }
  }
];

