const aiText =
  $json.output?.[0]?.content?.[0]?.text ||
  $json.content?.parts?.[0]?.text ||
  $json.text ||
  "";

let cleaned = aiText
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

const parsed = JSON.parse(cleaned);

return [
  {
    json: parsed
  }
];

const issueKey = $json.issue_key;
const summary = $json.summary;
const description = $json.description || "";

let cleanDescription = description
  .replace(/Acceptance Criteria:/gi, "")
  .replace(/\r/g, "")
  .trim();

let acceptanceCriteria = cleanDescription
  .split(/\s*\d+\.\s+/)
  .map(ac => ac.trim())
  .filter(ac => ac.length > 0);

if (acceptanceCriteria.length <= 1) {
  acceptanceCriteria = cleanDescription
    .split(/\n+/)
    .map(ac => ac.trim())
    .filter(ac => ac.length > 0);
}

return [
  {
    json: {
      issue_key: issueKey,
      summary,
      description,
      acceptance_criteria_count: acceptanceCriteria.length,
      acceptance_criteria: acceptanceCriteria
    }
  }
];

const issueKey = $json.issue_key;
const summary = $json.summary;
const testData = $json.test_data || [];

const iteration = $json.iteration;
const maxIterations = $json.max_iterations;
const acCoveragePercentage = $json.ac_coverage_percentage;
const qualityScore = $json.quality_score;
const criticStatus = $json.critic_status;
const criticFeedback = $json.critic_feedback || [];

const executionResults = [];

for (const td of testData) {
  let actualStatus = null;
  let responseBody = null;
  let executionStatus = "FAIL";
  let actualResult = "";
  let defectRequired = false;

  try {
    const response = await this.helpers.httpRequest({
      method: td.api_method || "GET",
      url: td.api_url,
      json: true,
      returnFullResponse: true,
      timeout: 10000,
      ignoreHttpStatusErrors: true
    });

    actualStatus = response.statusCode;
    responseBody = response.body;

    if (Number(actualStatus) === Number(td.expected_status)) {
      executionStatus = "PASS";
      actualResult = `Expected status ${td.expected_status} matched actual status ${actualStatus}.`;
      defectRequired = false;
    } else {
      executionStatus = "FAIL";
      actualResult = `Expected status ${td.expected_status}, but actual status was ${actualStatus}.`;
      defectRequired = true;
    }

  } catch (error) {
    actualStatus =
      error.response?.statusCode ||
      error.response?.status ||
      error.statusCode ||
      error.status ||
      "ERROR";

    responseBody =
      error.response?.body ||
      error.response?.data ||
      error.message;

    if (Number(actualStatus) === Number(td.expected_status)) {
      executionStatus = "PASS";
      actualResult = `Expected status ${td.expected_status} matched actual status ${actualStatus}.`;
      defectRequired = false;
    } else {
      executionStatus = "FAIL";
      actualResult = `API execution failed. Expected status ${td.expected_status}, actual status ${actualStatus}.`;
      defectRequired = true;
    }
  }

  executionResults.push({
    test_case_id: td.test_case_id,
    scenario: td.scenario,
    type: td.type,
    api_method: td.api_method || "GET",
    api_url: td.api_url,
    expected_status: td.expected_status,
    actual_status: actualStatus,
    request_data: td.request_data || {},
    response_body: responseBody,
    execution_status: executionStatus,
    actual_result: actualResult,
    defect_required: defectRequired
  });
}

const passed = executionResults.filter(r => r.execution_status === "PASS").length;
const failed = executionResults.filter(r => r.execution_status === "FAIL").length;

return [
  {
    json: {
      issue_key: issueKey,
      summary,
      iteration,
      max_iterations: maxIterations,
      ac_coverage_percentage: acCoveragePercentage,
      quality_score: qualityScore,
      critic_status: criticStatus,
      critic_feedback: criticFeedback,
      total_tests: executionResults.length,
      passed,
      failed,
      execution_status: failed === 0 ? "PASS" : "FAIL",
      execution_results: executionResults,
      test_data: testData
    }
  }
];

const issueKey = $json.issue_key;
const summary = $json.summary;
const executionResults = $json.execution_results || [];

const defects = [];

executionResults
  .filter(r => r.execution_status === "FAIL")
  .forEach((r, index) => {
    const isSecurity = String(r.type).toLowerCase().includes("security");

    defects.push({
      defect_id: `BUG_${String(index + 1).padStart(3, "0")}`,
      linked_story: issueKey,
      failed_test_case_id: r.test_case_id,
      defect_summary: isSecurity
        ? "Security issue: Unauthorized access to another customer's parcel details"
        : `API validation failed for ${r.test_case_id}`,
      defect_description:
        `Test Case ${r.test_case_id} failed.\n\n` +
        `Scenario: ${r.scenario}\n` +
        `API URL: ${r.api_url}\n` +
        `Expected Status: ${r.expected_status}\n` +
        `Actual Status: ${r.actual_status}\n\n` +
        `Response Body:\n${JSON.stringify(r.response_body, null, 2)}\n\n` +
        `Actual Result: ${r.actual_result}`,
      api_url: r.api_url,
      expected_status: r.expected_status,
      actual_status: r.actual_status,
      severity: isSecurity ? "Critical" : "High",
      priority: isSecurity ? "High" : "Medium",
      status: "Ready to Log"
    });
  });

return [
  {
    json: {
      issue_key: issueKey,
      summary,
      execution_status: $json.execution_status,
      total_tests: $json.total_tests,
      passed: $json.passed,
      failed: $json.failed,
      total_defects: defects.length,
      defects,

      critic_status: $json.critic_status,
      ac_coverage_percentage: $json.ac_coverage_percentage,
      quality_score: $json.quality_score,
      critic_feedback: $json.critic_feedback || [],

      execution_results: executionResults,
      test_data: $json.test_data || []
    }
  }
];

return [
  {
    json: {
      issue_key: $json.issue_key,
      jira_comment_body: {
        body: {
          type: "doc",
          version: 1,
          content: [
            {
              type: "paragraph",
              content: [
                {
                  type: "text",
                  text: $json.report
                }
              ]
            }
          ]
        }
      }
    }
  }
];
